const crypto = require('crypto');

const item = $input.first().json;
const body = item.body ?? item;
const headers = item.headers ?? {};

function pickHeader(name) {
  const direct = headers[name];
  if (typeof direct === 'string' && direct.trim() !== '') return direct.trim();
  const lower = headers[name.toLowerCase()];
  if (typeof lower === 'string' && lower.trim() !== '') return lower.trim();
  return null;
}

function normalizeOptionalString(value) {
  if (typeof value !== 'string') {
    return null;
  }
  const trimmed = value.trim();
  return trimmed === '' ? null : trimmed;
}

function sanitizeRawPayload(value) {
  if (value == null || typeof value !== 'object') {
    return {};
  }
  const secretPattern = /^(token|secret|password|authorization|api[_-]?key)$/i;
  if (Array.isArray(value)) {
    return value.map((entry) =>
      typeof entry === 'object' && entry !== null ? sanitizeRawPayload(entry) : entry
    );
  }
  const out = {};
  for (const [key, val] of Object.entries(value)) {
    if (secretPattern.test(key)) {
      out[key] = '[REDACTED]';
    } else if (typeof val === 'object' && val !== null) {
      out[key] = sanitizeRawPayload(val);
    } else {
      out[key] = val;
    }
  }
  return out;
}

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function resolveCorrelationId() {
  const candidate =
    normalizeOptionalString(body.correlation_id) ||
    normalizeOptionalString(pickHeader('X-Correlation-Id'));
  if (candidate && uuidPattern.test(candidate)) {
    return candidate;
  }
  return crypto.randomUUID();
}

const businessId =
  normalizeOptionalString(body.business_id) ||
  (typeof $env !== 'undefined' && $env.ALPSTEIN_WEBSITE_CHAT_BUSINESS_ID
    ? $env.ALPSTEIN_WEBSITE_CHAT_BUSINESS_ID
    : null);

if (!businessId) {
  throw new Error('Validation: business_id is required');
}

const text = normalizeOptionalString(body.text);
if (!text) {
  throw new Error('Validation: text is required');
}

const visitorId = normalizeOptionalString(body.visitor_id);
if (!visitorId) {
  throw new Error('Validation: visitor_id is required');
}

const sessionId = normalizeOptionalString(body.session_id);
if (!sessionId) {
  throw new Error('Validation: session_id is required');
}

let messageId = normalizeOptionalString(body.message_id);
if (!messageId) {
  const fallbackSeed = `${sessionId}|${text}|${normalizeOptionalString(body.timestamp) || new Date().toISOString()}`;
  messageId = `generated-${crypto.createHash('sha256').update(fallbackSeed).digest('hex').slice(0, 24)}`;
}

const correlationId = resolveCorrelationId();

const isoTimestamp = normalizeOptionalString(body.timestamp) || new Date().toISOString();

const source = {
  platform: 'web_widget_v1',
  account_id: normalizeOptionalString(body.website_id),
  account_name: normalizeOptionalString(body.website_name),
  locale: normalizeOptionalString(body.language),
  country: normalizeOptionalString(body.country),
  region: normalizeOptionalString(body.region),
  timezone: normalizeOptionalString(body.timezone)
};

const attribution = {
  marketing_source: normalizeOptionalString(body.marketing_source),
  campaign_id: normalizeOptionalString(body.campaign_id),
  landing_page_url: normalizeOptionalString(body.page_url),
  referrer_url: normalizeOptionalString(body.referrer),
  utm_source: normalizeOptionalString(body.utm_source),
  utm_medium: normalizeOptionalString(body.utm_medium),
  utm_campaign: normalizeOptionalString(body.utm_campaign),
  utm_content: normalizeOptionalString(body.utm_content),
  utm_term: normalizeOptionalString(body.utm_term)
};

const userAgentHeader = pickHeader('User-Agent');
const userAgentBody = normalizeOptionalString(body.user_agent);
const ip = pickHeader('x-forwarded-for') || pickHeader('x-real-ip');

const messageClient = {
  user_agent: userAgentBody || userAgentHeader,
  ip_address_hash: ip
    ? crypto.createHash('sha256').update(String(ip)).digest('hex')
    : null
};

const rawPayload = sanitizeRawPayload({
  website_payload: body,
  website_headers: {
    host: pickHeader('host'),
    origin: pickHeader('origin'),
    referer: pickHeader('referer')
  }
});

return [
  {
    json: {
      correlation_id: correlationId,
      business_id: businessId,
      channel: 'website_chat',
      source,
      attribution,
      customer: {
        phone: normalizeOptionalString(body.phone),
        name: normalizeOptionalString(body.name),
        email: normalizeOptionalString(body.email),
        external_customer_id: visitorId
      },
      message: {
        text,
        external_message_id: `web:${sessionId}:${messageId}`,
        external_conversation_id: `web:${sessionId}`,
        timestamp: isoTimestamp,
        client: messageClient,
        raw_payload: rawPayload
      },
      website_chat_context: {
        visitor_id: visitorId,
        session_id: sessionId,
        message_id: messageId
      }
    }
  }
];

const backend = $input.first().json;
const normalized = $('Normalize Website Chat Incoming').first().json;
const ctx = normalized.website_chat_context;

if (backend.success !== true || !backend.data) {
  return [
    {
      json: {
        success: false,
        correlation_id: normalized.correlation_id,
        session_id: ctx.session_id,
        visitor_id: ctx.visitor_id,
        error: {
          code: backend.error?.code || 'BACKEND_RESPONSE_FAILED',
          message: backend.error?.message || 'Backend request was not successful'
        }
      }
    }
  ];
}

return [
  {
    json: {
      success: true,
      correlation_id: normalized.correlation_id,
      session_id: ctx.session_id,
      visitor_id: ctx.visitor_id,
      message: {
        id: `ai:${Date.now()}`,
        text: (backend.data.reply_to_customer || '').trim() || 'Thank you for your message.',
        is_duplicate: backend.data.message?.is_duplicate === true
      }
    }
  }
];

const normalized = $('Normalize Website Chat Incoming').first().json;
const ctx = normalized.website_chat_context;

return [
  {
    json: {
      success: false,
      correlation_id: normalized.correlation_id,
      session_id: ctx.session_id,
      visitor_id: ctx.visitor_id,
      error: {
        code: 'N8N_BACKEND_REQUEST_FAILED',
        message: 'Service is temporarily unavailable. Please retry.'
      }
    }
  }
];

const backend = $('POST Backend').first().json;
const data = backend.data || {};
const notification = data.notification || {};
const normalized = $('Normalize Website Chat Incoming').first().json;

const customerText = normalized?.message?.text?.trim() || null;
const customerName = normalized?.customer?.name || null;
const pageUrl = normalized?.attribution?.landing_page_url || null;
const utmSource = normalized?.attribution?.utm_source || null;
const leadStatus = data.lead?.status || null;
const leadPriority = data.lead?.priority || null;

const type = notification.notification_type || 'system_error';
const reason = notification.reason || 'unknown';
const priority = notification.priority || 'normal';

const lines = [
  `[Alpstein][Website Chat] ${type}`,
  `Priority: ${priority}`,
  `Reason: ${reason}`
];

if (customerName) lines.push(`Customer: ${customerName}`);
if (customerText) lines.push(`Message: ${customerText.slice(0, 280)}`);
if (pageUrl) lines.push(`Page: ${pageUrl}`);
if (utmSource) lines.push(`UTM source: ${utmSource}`);
if (leadStatus) {
  const lp = leadPriority ? ` (${leadPriority})` : '';
  lines.push(`Lead: ${leadStatus}${lp}`);
}

return [
  {
    json: {
      telegram_text: lines.join('\n')
    }
  }
];
